// The foyer as sent inside a universite (its own links are hidden by @JsonIgnore in the back)
export interface FoyerResume {
  idFoyer: number;
  nomFoyer: string;
  capaciteFoyer: number;
}

// Same fields as the JSON returned by the back (entity Universite)
export interface Universite {
  idUniversite: number;
  nomUniversite: string;
  adresse: string;
  foyer?: FoyerResume | null;
}

// Body of POST /add: the id is generated by the database
export type NouvelleUniversite = Pick<Universite, 'nomUniversite' | 'adresse'>;

// Body of PUT /update (UniversiteDTO): the foyer is kept by the back
export type UniversiteModifiee = Pick<Universite, 'idUniversite' | 'nomUniversite' | 'adresse'>;
